const mCPCapabilityStats = `-- name: MCPCapabilityStats :many
SELECT c.server_id, c.kind,
       count(*) FILTER (WHERE c.gone_at IS NULL)::bigint AS listed,
       count(*) FILTER (WHERE c.gone_at IS NULL AND c.approved_fingerprint = c.fingerprint)::bigint AS approved,
       count(*) FILTER (WHERE c.gone_at IS NULL AND c.approved_fingerprint IS DISTINCT FROM c.fingerprint)::bigint AS unapproved
FROM mcp_capabilities c
WHERE c.server_id = ANY($1::uuid[])
GROUP BY c.server_id, c.kind
`

type MCPCapabilityStatsRow struct {
	ServerID   uuid.UUID
	Kind       string
	Listed     int64
	Approved   int64
	Unapproved int64
}

// Per server and kind: listed capabilities, the approved ones, and the
// listed ones whose current definition is not approved.
func (q *Queries) MCPCapabilityStats(ctx context.Context, serverIds []uuid.UUID) ([]MCPCapabilityStatsRow, error) {
	rows, err := q.db.Query(ctx, mCPCapabilityStats, serverIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []MCPCapabilityStatsRow{}
	for rows.Next() {
		var i MCPCapabilityStatsRow
		if err := rows.Scan(
			&i.ServerID,
			&i.Kind,
			&i.Listed,
			&i.Approved,
			&i.Unapproved,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const markMCPCapabilitiesGone = `-- name: MarkMCPCapabilitiesGone :many
UPDATE mcp_capabilities c
SET gone_at = now(), approved_fingerprint = NULL, approved_by = NULL, approved_at = NULL,
    tool_class = NULL, class_set_by = NULL, class_set_at = NULL
WHERE c.server_id = $1 AND c.gone_at IS NULL
  -- listed holds "kind name" for every capability the refresh listed.
  AND NOT ((c.kind || ' ' || c.name) = ANY($2::text[]))
RETURNING c.kind, c.name
`

type MarkMCPCapabilitiesGoneParams struct {
	ServerID uuid.UUID
	Listed   []string
}

type MarkMCPCapabilitiesGoneRow struct {
	Kind string
	Name string
}

// Marks the server's listed capabilities that the refresh didn't list as
// gone, and withdraws their approval.
func (q *Queries) MarkMCPCapabilitiesGone(ctx context.Context, arg MarkMCPCapabilitiesGoneParams) ([]MarkMCPCapabilitiesGoneRow, error) {
	rows, err := q.db.Query(ctx, markMCPCapabilitiesGone, arg.ServerID, arg.Listed)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []MarkMCPCapabilitiesGoneRow{}
	for rows.Next() {
		var i MarkMCPCapabilitiesGoneRow
		if err := rows.Scan(&i.Kind, &i.Name); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

